abstract class MediaFile { String fileName; double duration,fileSize; MediaFile(String fileName,double duration,double fileSize){this.fileName=fileName;this.duration=duration;this.fileSize=fileSize;} abstract void play();abstract void pause();abstract void stop(); }
class AudioFile extends MediaFile { AudioFile(String name,double duration,double size){super(name,duration,size);}void play(){System.out.println("Playing audio file: "+fileName);}void pause(){System.out.println("Pausing audio file: "+fileName);}void stop(){System.out.println("Stopping audio file: "+fileName);} }
class VideoFile extends MediaFile { VideoFile(String name,double duration,double size){super(name,duration,size);}void play(){System.out.println("Playing video file: "+fileName);}void pause(){System.out.println("Pausing video file: "+fileName);}void stop(){System.out.println("Stopping video file: "+fileName);} }
class LiveStream extends MediaFile { LiveStream(String name,double duration,double size){super(name,duration,size);}void play(){System.out.println("Streaming live: "+fileName);}void pause(){System.out.println("Live stream paused: "+fileName);}void stop(){System.out.println("Live stream stopped: "+fileName);} }
public class MediaPlayerTest { public static void main(String[] args){MediaFile m=new AudioFile("song.mp3",3.5,5);m.play();m.pause();m.stop();System.out.println("----------------------");m=new VideoFile("movie.mp4",120,700);m.play();m.pause();m.stop();System.out.println("----------------------");m=new LiveStream("Live News",0,0);m.play();m.pause();m.stop();} }
